function validate(input) {
  const [{ Prices = [], UnitsSold = [] }] = input;
  const periods = new Map();
  for (const row of Prices) {
    if (row.some((v) => v === null)) return 'Prices rows may not contain null.';
    const [id, start, end, price] = row;
    if (start > end) return `A period of product ${id} ends before it starts.`;
    if (price < 0) return 'Prices may not be negative.';
    if (!periods.has(id)) periods.set(id, []);
    periods.get(id).push([start, end]);
  }
  for (const [id, list] of periods) {
    list.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
    for (let i = 1; i < list.length; i++) if (list[i][0] <= list[i - 1][1]) return `Product ${id} has overlapping price periods.`;
  }
  for (const row of UnitsSold) {
    if (row.some((v) => v === null)) return 'UnitsSold rows may not contain null.';
    const [id, day, units] = row;
    if (units < 1) return 'Every sale needs at least one unit.';
    if (!(periods.get(id) ?? []).some(([s, e]) => s <= day && day <= e)) return `The sale of product ${id} on ${day} has no price period.`;
  }
  return null;
}

