function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const iso = (k) => new Date(Date.UTC(2019, 0, 1) + k * 86400000).toISOString().slice(0, 10);
  const small = size === 'small';
  const products = small ? 1 + pick(4) : 300;
  const Prices = [], UnitsSold = [], all = [];
  for (let id = 1; id <= products; id++) {
    const count = small ? 1 + pick(2) : 1 + pick(5);
    let day = pick(small ? 10 : 60);
    for (let k = 0; k < count; k++) {
      const length = small ? 1 + pick(5) : 1 + pick(40);
      const period = [id, iso(day), iso(day + length - 1), small ? [5, 10, 15, 20, 30][pick(5)] : 1 + pick(200)];
      Prices.push(period);
      all.push([period, day, length]);
      day += length + (rand() < 0.3 ? 1 + pick(5) : 0);
    }
  }
  const sales = small ? pick(9) : 2000;
  // Some products are left without sales so the zero rule is exercised.
  const sellers = all.filter(([p]) => small || p[0] % 7 !== 0);
  for (let i = 0; i < sales && sellers.length; i++) {
    const [period, start, length] = sellers[pick(sellers.length)];
    const offset = rand() < 0.3 ? (rand() < 0.5 ? 0 : length - 1) : pick(length);
    UnitsSold.push([period[0], iso(start + offset), small ? [1, 2, 3, 10, 15][pick(5)] : 1 + pick(100)]);
    if (small && rand() < 0.2 && i + 1 < sales) { UnitsSold.push(UnitsSold.at(-1).slice()); i++; }
  }
  return [{ Prices, UnitsSold }];
}
